css:
.ps-site-footer { background: var(--ps-surface-subtle); border-top: 1px solid var(--ps-border-subtle); }
.ps-site-footer__brand { margin-bottom: var(--ps-space-6, 24px); }
.ps-site-footer__brand-name { display: block; font-weight: 700; font-size: 1rem; color: var(--ps-ink-primary); }
.ps-site-footer__tagline { margin: var(--ps-space-2, 4px) 0 0; font-size: 0.8125rem; color: var(--ps-ink-secondary); }
.ps-site-footer__heading { text-transform: uppercase; letter-spacing: 0.08em; font-size: 0.6875rem; font-weight: 600; color: var(--ps-ink-disabled); }
.ps-site-footer__identity-row { display: flex; align-items: center; gap: var(--ps-space-2, 4px); font-size: 0.8125rem; color: var(--ps-ink-secondary); }
.ps-site-footer__identity-row--locations { justify-content: space-between; }
.ps-site-footer__identity-row--muted { font-size: 0.75rem; color: var(--ps-ink-disabled); }
.ps-site-footer__identity-row--trademark { font-size: 0.6875rem; color: var(--ps-ink-disabled); max-width: 60ch; }
.ps-site-footer__locations::after { content: ''; }
